def site(p, r, name, reg):
    sub = {"P": p, "D": p + 16, "J": p + 24, "U": p + 28, "N": p + 40}
    s = TEMPLATE
    for k, v in sub.items():
        s = s.replace("{" + k + "}", "%08x" % v)
    s = s.replace("{r}", str(r)).replace("{name}", name).replace("{reg}", reg)
    return s + (
        "/-- The free site at `0x%08x` as a `KSite`. -/\n"
        "theorem ksite_%08x {live : Nat → Prop} {S : Nat → Prop}\n"
        "    {Q : (Nat → BitVec 64) → (Nat → BitVec 8) → Prop} {fr : Nat → Prop}\n"
        "    (hlive : ∀ p ∈ dcText, live p.1) :\n"
        "    KSite live S Q 0x%08x#64 0x%08x#64 fr (fun R _ x => RegLoc %d R x) :=\n"
        "  fun _ _ _ _ _ _ _ h hr hnv hl hk => kfree_%08x hlive h hr hnv hl.ptr hl.fl hk\n\n"
        % (p, p, p, p + 40, r, p))


SLOT_TEMPLATE = "/-- The slot cleared at `0x{C}`. -/\ntheorem kclear_{C} {live : Nat → Prop} {S : Nat → Prop}\n    {Q : (Nat → BitVec 64) → (Nat → BitVec 8) → Prop} {fr : Nat → Prop} (hlive : ∀ p ∈ dcText, live p.1)\n    {M0 M1 : Mem} {R0 R : Nat → BitVec 64} {H H' : Heap} {F F' : List Blk} {L1 L2 L' : List NumObj}\n    {x : NumObj} {sp : Nat} (hkf : KFreed H F L1 L2 x H' F' L') (hb : BcHeap S M1 H' F' L')\n    (hout : ∀ a, OutHeap a → imgM M1 a = imgM M0 a) (hkp : Keeps [1, 10, 14, 15] R R0)\n    (hR2 : R 2 = BitVec.ofNat 64 sp) (ks : KSlot S fr (sp + {o}))\n    (hk : KFreeK live S Q 0x{N}#64 R0 M0 fr H F L1 L2 x) :\n    DW live S Q 0x{C}#64 R M1 := by\n  have hS : HeapOwn S := fun a h1 h2 => hb.heap.own a h1 h2\n  have hal := ks.al; have hlo := ks.lo; have hhi := ks.hi\n  have htx : tohostAddr = 0x8001ad00 := rfl\n  bc_run hlive hS [hR2] at 0x{N}\n  all_goals first | exact ks.own | (simp only [StOK, and_true]; omega) | skip\n  refine hk _ _ _ _ _ (by keeps_tac hkp) hkf\n    (hb.out_frame (MemOnly.store _ _ _ _) fun a ha => ks.out a ha.1 ha.2) fun a ha hn => ?_\n  have : a < sp + {o} ∨ sp + {o} + 8 ≤ a :=\n    Classical.byContradiction fun hc => hn (ks.fr a (by omega) (by omega))\n  rw [imgM_store_miss _ _ this, hout a ha]\n\n/-- The struct pushed on `_bc_Free_list` at `0x{U}`, then the slot\ncleared. -/\ntheorem kspush_{U} {live : Nat → Prop} {S : Nat → Prop}\n    {Q : (Nat → BitVec 64) → (Nat → BitVec 8) → Prop} {fr : Nat → Prop} (hlive : ∀ p ∈ dcText, live p.1)\n    {M0 M1 : Mem} {R0 R : Nat → BitVec 64} {H H' : Heap} {F : List Blk} {L1 L2 : List NumObj}\n    {x : NumObj} {sp : Nat} (hr1 : x.rep.refs = 1)\n    (hpost : BcHeap S (writeLog (writeLog M1 [(bcFreeAddr, 8, BitVec.ofNat 64 x.rep.p)])\n      [(x.rep.p + 16, 8, BitVec.ofNat 64 (deadHead F))]) H' (x.sb :: F) (L1 ++ L2))\n    (hout : ∀ a, OutHeap a → imgM M1 a = imgM M0 a)\n    (wg : ldv .ld M1 bcFreeAddr = BitVec.ofNat 64 (deadHead F))\n    (hS : HeapOwn S) (hgl : ∀ a, bcFreeAddr ≤ a → a < bcFreeAddr + 8 → S a)\n    (hp : 2147603920 ≤ x.rep.p) (hp' : x.rep.p + 40 ≤ 2273312768) (hpa : x.rep.p % 8 = 0)\n    (hkp : Keeps [1, 10, 14, 15] R R0)\n    (hx : R 15 = BitVec.ofNat 64 x.rep.p) (h25 : R 25 = BitVec.ofNat 64 bcFreeAddr)\n    (hR2 : R 2 = BitVec.ofNat 64 sp) (ks : KSlot S fr (sp + {o}))\n    (hk : KFreeK live S Q 0x{N}#64 R0 M0 fr H F L1 L2 x) :\n    DW live S Q 0x{U}#64 R M1 := by\n  have htx : tohostAddr = 0x8001ad00 := rfl\n  have hgl' : ∀ b ∈ accAddrs 2147601840 8, S b := fun b hb => by\n    have := of_mem_accAddrs hb\n    exact hgl b (by simp only [bcFreeAddr]; omega) (by simp only [bcFreeAddr]; omega)\n  simp only [bcFreeAddr] at wg h25 hpost ⊢\n  apply st_{U} hlive\n  · bsimp [h25]; bc_addr\n  · bsimp [h25]; exact hgl'\n  bsimp [h25, wg]\n  bc_run hlive hS [hx, h25] at 0x{C}\n  all_goals first | exact hgl' | (simp only [StOK, and_true]; omega) | skip\n  refine kclear_{C} hlive (.rel hr1) hpost (fun a ha => ?_) (by keeps_tac hkp) (by bsimp [hR2]) ks hk\n  have ha' := ha\n  simp only [OutHeap, heapStart, heapEnd, bcFreeAddr] at ha'\n  rw [imgM_store_miss _ _ (by omega), imgM_store_miss _ _ (by omega), hout a ha]\n\n/-- An owner's buffer freed, from `0x{D}` (`n_refs` now `0`); `a5`\nreloaded from the slot. -/\ntheorem kfree_owner_{D} {live : Nat → Prop} {S : Nat → Prop}\n    {Q : (Nat → BitVec 64) → (Nat → BitVec 8) → Prop} {fr : Nat → Prop} (hlive : ∀ p ∈ dcText, live p.1)\n    {M M1 : Mem} {R0 R : Nat → BitVec 64} {H : Heap} {F : List Blk} {L1 L2 : List NumObj}\n    {x : NumObj} {sp : Nat} (h : BcHeap S M H F (L1 ++ x :: L2)) (ho : x.Owns)\n    (hnv : x.Owns → ∀ y ∈ L1, y.db ≠ x.db) (hr1 : x.rep.refs = 1) {v : BitVec 64}\n    (hM1 : M1 = writeLog M [(x.rep.p + 12, 4, v)])\n    (hi1 : HeapInv S M1 H) (wg : ldv .ld M1 2147601840 = BitVec.ofNat 64 (deadHead F))\n    (hfr1 : ∀ a, OutHeap a → imgM M1 a = imgM M a) (hkp : Keeps [1, 10, 14, 15] R R0)\n    (hx : R 15 = BitVec.ofNat 64 x.rep.p) (h25 : R 25 = BitVec.ofNat 64 bcFreeAddr)\n    (hR2 : R 2 = BitVec.ofNat 64 sp) (ks : KSlot S fr (sp + {o}))\n    (hslot : ldv .ld M (sp + {o}) = BitVec.ofNat 64 x.rep.p)\n    (hk : KFreeK live S Q 0x{N}#64 R0 M fr H F L1 L2 x) :\n    DW live S Q 0x{D}#64 R M1 := by\n  have hi := h.heap\n  have hS : HeapOwn S := fun a h1 h2 => hi.own a h1 h2\n  have hxm : x ∈ L1 ++ x :: L2 := List.mem_append_right _ List.mem_cons_self\n  have hn := h.nums x hxm\n  have hxb := h.blocks x hxm\n  num_facts hn\n  have hpt : ldv .ld M1 (x.rep.p + 24) = BitVec.ofNat 64 x.rep.ptr := by\n    rw [hM1, ldv_ld_miss _ _ (by omega)]; exact hn.ptr\n  have hdp : x.rep.ptr = x.db.pay := hxb.dPay ho\n  have fbd := hi.blk (List.mem_append_right _ hxb.dLive)\n  have hd1 : 2147603920 ≤ x.db.h := fbd.lo\n  have hdph : x.db.pay = x.db.h + 16 := rfl\n  have htx : tohostAddr = 0x8001ad00 := rfl\n  have hlo := ks.lo; have hhi := ks.hi\n  have hso1 : ldv .ld M1 (sp + {o}) = BitVec.ofNat 64 x.rep.p := by\n    have := ks.out (sp + {o}) (by omega) (by omega)\n    simp only [OutHeap, heapStart, heapEnd] at this\n    rw [hM1, ldv_ld_miss _ _ (by omega)]; exact hslot\n  bc_run hlive hS [hx, hpt] at 0x{J} 0x{U}\n  · intro hc\n    exact absurd ((ofNat_eq_iff (x := x.rep.ptr) (y := 0) (by omega) (by omega)).mp hc) (by omega)\n  intro _\n  obtain ⟨lpre, lpost, hl⟩ := List.append_of_mem hxb.dLive\n  apply st_{J} hlive\n  refine free_spec hlive hi1 hl _ (by bsimp [hdp]) (by bsimp []) ?_\n  intro R1 Mt3 hk1 hfp\n  bsimp []\n  have wg3 : ldv .ld Mt3 2147601840 = BitVec.ofNat 64 (deadHead F) := by\n    rw [ldv_congr .ld fun j hj => hfp.frame _ fun ha => by\n      rcases AllocByte.glob_or_heap hi ha with h' | h' <;>\n        simp only [freeListAddr, heapStart, heapEnd, widthOfM] at h' hj <;> omega]\n    exact wg\n  have hso3 : ldv .ld Mt3 (sp + {o}) = BitVec.ofNat 64 x.rep.p := by\n    rw [ldv_congr .ld fun j hj => hfp.frame _ (OutHeap.not_alloc hi1\n      (ks.out _ (by omega) (by simp only [widthOfM] at hj; omega)))]\n    exact hso1\n  have h2 : R1 2 = BitVec.ofNat 64 sp := by rw [hk1.get 2]; bsimp [hR2]\n  bc_run hlive hS [h2, hso3] at 0x{U}\n  all_goals first | exact ks.own | skip\n  subst hM1\n  exact kspush_{U} hlive hr1 (h.freeOwner ho (hnv ho) hl hfp)\n    (fun a ha => (hfp.frame a (OutHeap.not_alloc hi ha)).trans (hfr1 a ha)) wg3 hS h.globOwn\n    (by omega) (by omega) (by omega) (by keeps_tac ((hk1.mono (by decide)).trans (by keeps_tac hkp)))\n    (by bsimp [hso3]) (by bsimp [hk1.get 25, h25]) (by bsimp [h2]) ks hk\n\n/-- A view's struct released, from `0x{D}` (`n_refs` now `0`). -/\ntheorem kfree_view_{D} {live : Nat → Prop} {S : Nat → Prop}\n    {Q : (Nat → BitVec 64) → (Nat → BitVec 8) → Prop} {fr : Nat → Prop} (hlive : ∀ p ∈ dcText, live p.1)\n    {M : Mem} {R0 R : Nat → BitVec 64} {H : Heap} {F : List Blk} {L1 L2 : List NumObj}\n    {x : NumObj} {sp : Nat} (h : BcHeap S M H F (L1 ++ x :: L2)) (hv : ¬ x.Owns)\n    (hr1 : x.rep.refs = 1) (v : BitVec 64) (hkp : Keeps [1, 10, 14, 15] R R0)\n    (hx : R 15 = BitVec.ofNat 64 x.rep.p) (h25 : R 25 = BitVec.ofNat 64 bcFreeAddr)\n    (hR2 : R 2 = BitVec.ofNat 64 sp) (ks : KSlot S fr (sp + {o}))\n    (hk : KFreeK live S Q 0x{N}#64 R0 M fr H F L1 L2 x) :\n    DW live S Q 0x{D}#64 R (writeLog M [(x.rep.p + 12, 4, v)]) := by\n  have hi := h.heap\n  have hS : HeapOwn S := fun a h1 h2 => hi.own a h1 h2\n  have hxm : x ∈ L1 ++ x :: L2 := List.mem_append_right _ List.mem_cons_self\n  have hn := h.nums x hxm\n  num_facts hn\n  have hv0 : x.rep.ptr = 0 := Classical.not_not.mp hv\n  have htx : tohostAddr = 0x8001ad00 := rfl\n  bc_run hlive hS [hx] at 0x{U}\n  rotate_left\n  · intro hc; rw [ldv_ld_miss _ _ (by omega), hn.ptr, hv0] at hc; exact absurd rfl hc\n  intro _\n  exact kspush_{U} hlive hr1 (h.freeView hv v)\n    (fun a ha => by simp only [OutHeap, heapStart, heapEnd] at ha; exact imgM_store_miss _ _ (by omega))\n    (by rw [ldv_ld_miss _ _ (by simp only [bcFreeAddr]; omega)]; exact h.dead.head) hS h.globOwn\n    (by omega) (by omega) (by omega) (by keeps_tac hkp) (by bsimp [hx]) (by bsimp [h25])\n    (by bsimp [hR2]) ks hk\n\n/-- The last reference dropped at `0x{L}` (`a5` holds the number). -/\ntheorem kfree_rel_{L} {live : Nat → Prop} {S : Nat → Prop}\n    {Q : (Nat → BitVec 64) → (Nat → BitVec 8) → Prop} {fr : Nat → Prop} (hlive : ∀ p ∈ dcText, live p.1)\n    {M : Mem} {R0 R : Nat → BitVec 64} {H : Heap} {F : List Blk} {L1 L2 : List NumObj}\n    {x : NumObj} {sp : Nat} (h : BcHeap S M H F (L1 ++ x :: L2)) (hr1 : x.rep.refs = 1)\n    (hnv : x.Owns → ∀ y ∈ L1, y.db ≠ x.db) (hkp : Keeps [1, 10, 14, 15] R R0)\n    (hx : R 15 = BitVec.ofNat 64 x.rep.p) (h25 : R 25 = BitVec.ofNat 64 bcFreeAddr)\n    (hR2 : R 2 = BitVec.ofNat 64 sp) (ks : KSlot S fr (sp + {o}))\n    (hslot : ldv .ld M (sp + {o}) = BitVec.ofNat 64 x.rep.p)\n    (hk : KFreeK live S Q 0x{N}#64 R0 M fr H F L1 L2 x) :\n    DW live S Q 0x{L}#64 R M := by\n  have hi := h.heap\n  have hS : HeapOwn S := fun a h1 h2 => hi.own a h1 h2\n  have hxm : x ∈ L1 ++ x :: L2 := List.mem_append_right _ List.mem_cons_self\n  have hn := h.nums x hxm\n  have hxb := h.blocks x hxm\n  num_facts hn\n  have hrf := hn.refs\n  have htx : tohostAddr = 0x8001ad00 := rfl\n  have h0 : BitVec.ofNat 64 1 + 18446744073709551615#64 = 0#64 := by decide\n  bc_run hlive hS [hx, hrf, hr1, h0] at 0x{C} 0x{D}\n  by_cases ho : x.Owns\n  · have hpp : x.rep.p = x.sb.pay := hxb.sPay\n    have hsz := hxb.sSz\n    have hsph : x.sb.pay = x.sb.h + 16 := rfl\n    exact kfree_owner_{D} hlive h ho hnv hr1 rfl\n      (hi.transport fun a ha => by\n        have hn := live_not_alloc hi hxb.sLive (a := a)\n        refine imgM_store_miss _ _ (Classical.byContradiction fun hc => hn ⟨by omega, ?_⟩ ha)\n        simp only [Blk.fin] at hc ⊢; omega)\n      (by rw [ldv_ld_miss _ _ (by omega)]; exact h.dead.head)\n      (fun a ha => by simp only [OutHeap, heapStart, heapEnd] at ha; exact imgM_store_miss _ _ (by omega))\n      (by keeps_tac hkp) (by bsimp [hx]) (by bsimp [h25]) (by bsimp [hR2]) ks hslot hk\n  · exact kfree_view_{D} hlive h ho hr1 _ (by keeps_tac hkp) (by bsimp [hx])\n      (by bsimp [h25]) (by bsimp [hR2]) ks hk\n\n/-- One reference fewer at `0x{L}`. -/\ntheorem kfree_dec_{L} {live : Nat → Prop} {S : Nat → Prop}\n    {Q : (Nat → BitVec 64) → (Nat → BitVec 8) → Prop} {fr : Nat → Prop} (hlive : ∀ p ∈ dcText, live p.1)\n    {M : Mem} {R0 R : Nat → BitVec 64} {H : Heap} {F : List Blk} {L1 L2 : List NumObj}\n    {x : NumObj} {sp : Nat} (h : BcHeap S M H F (L1 ++ x :: L2)) (hr2 : 2 ≤ x.rep.refs)\n    (hkp : Keeps [1, 10, 14, 15] R R0) (hx : R 15 = BitVec.ofNat 64 x.rep.p)\n    (hR2 : R 2 = BitVec.ofNat 64 sp) (ks : KSlot S fr (sp + {o}))\n    (hk : KFreeK live S Q 0x{N}#64 R0 M fr H F L1 L2 x) :\n    DW live S Q 0x{L}#64 R M := by\n  have hi := h.heap\n  have hS : HeapOwn S := fun a h1 h2 => hi.own a h1 h2\n  have hxm : x ∈ L1 ++ x :: L2 := List.mem_append_right _ List.mem_cons_self\n  have hn := h.nums x hxm\n  num_facts hn\n  have hrf := hn.refs\n  have htx : tohostAddr = 0x8001ad00 := rfl\n  have hpr : BitVec.ofNat 64 x.rep.refs + 18446744073709551615#64 =\n      BitVec.ofNat 64 (x.rep.refs - 1) := word_pred (by omega)\n  have hsx : BitVec.signExtend 64 (BitVec.extractLsb 31 0 (BitVec.ofNat 64 (x.rep.refs - 1))) =\n      BitVec.ofNat 64 (x.rep.refs - 1) := sxw_ofNat (by omega)\n  bc_run hlive hS [hx, hrf, hpr, hsx] at 0x{C} 0x{D}\n  all_goals try (intro hc; exact absurd ((ofNat_eq_iff (x := x.rep.refs - 1) (y := 0)\n    (by omega) (by omega)).mp (Classical.not_not.mp hc)) (by omega))\n  intro _\n  refine kclear_{C} hlive (.dec hr2) (h.setRefs (toNat_ofNat_mod32 (by omega)) (by omega))\n    (fun a ha => ?_) (by keeps_tac hkp) (by bsimp [hR2]) ks hk\n  simp only [OutHeap, heapStart, heapEnd] at ha\n  exact imgM_store_miss _ _ (by omega)\n\n/-- **The free of `{name}`** (slot `sp+{o}`) at `0x{P}`. -/\ntheorem kfree_{P} {live : Nat → Prop} {S : Nat → Prop}\n    {Q : (Nat → BitVec 64) → (Nat → BitVec 8) → Prop} {fr : Nat → Prop} (hlive : ∀ p ∈ dcText, live p.1)\n    {M : Mem} {R : Nat → BitVec 64} {H : Heap} {F : List Blk} {L1 L2 : List NumObj}\n    {x : NumObj} {sp : Nat} (h : BcHeap S M H F (L1 ++ x :: L2)) (hr : 1 ≤ x.rep.refs)\n    (hnv : x.rep.refs = 1 → x.Owns → ∀ y ∈ L1, y.db ≠ x.db) (h25 : R 25 = BitVec.ofNat 64 bcFreeAddr)\n    (hR2 : R 2 = BitVec.ofNat 64 sp) (ks : KSlot S fr (sp + {o}))\n    (hslot : ldv .ld M (sp + {o}) = BitVec.ofNat 64 x.rep.p)\n    (hk : KFreeK live S Q 0x{N}#64 R M fr H F L1 L2 x) :\n    DW live S Q 0x{P}#64 R M := by\n  have hi := h.heap\n  have hS : HeapOwn S := fun a h1 h2 => hi.own a h1 h2\n  have hxm : x ∈ L1 ++ x :: L2 := List.mem_append_right _ List.mem_cons_self\n  have hn := h.nums x hxm\n  num_facts hn\n  have htx : tohostAddr = 0x8001ad00 := rfl\n  have hlo := ks.lo; have hhi := ks.hi\n  bc_run hlive hS [hR2, hslot] at 0x{L}\n  all_goals first | exact ks.own | skip\n  · intro hc\n    exact absurd ((ofNat_eq_iff (x := x.rep.p) (y := 0) (by omega) (by omega)).mp hc) (by omega)\n  intro _\n  rcases (show x.rep.refs = 1 ∨ 2 ≤ x.rep.refs from by omega) with hr1 | hr2\n  · exact kfree_rel_{L} hlive h hr1 (hnv hr1) (by keeps_tac Keeps.refl _ _) (by bsimp [])\n      (by bsimp [h25]) (by bsimp [hR2]) ks hslot hk\n  · exact kfree_dec_{L} hlive h hr2 (by keeps_tac Keeps.refl _ _) (by bsimp [])\n      (by bsimp [hR2]) ks hk\n\n"


def slot_site(p, o, name):
    sub = {"P": p, "L": p + 8, "D": p + 24, "J": p + 32, "U": p + 40, "C": p + 52, "N": p + 56}
    s = SLOT_TEMPLATE
    for k, v in sub.items():
        s = s.replace("{" + k + "}", "%08x" % v)
    s = s.replace("{o}", str(o)).replace("{name}", name)
    return s + (
        "/-- The free site at `0x%08x` as a `KSite`. -/\n"
        "theorem ksite_%08x {live : Nat → Prop} {S : Nat → Prop}\n"
        "    {Q : (Nat → BitVec 64) → (Nat → BitVec 8) → Prop} {fr : Nat → Prop}\n"
        "    (hlive : ∀ p ∈ dcText, live p.1) (sp : Nat) :\n"
        "    KSite live S Q 0x%08x#64 0x%08x#64 fr (SlotLoc S fr sp %d) :=\n"
        "  fun _ _ _ _ _ _ _ h hr hnv hl hk =>\n"
        "    kfree_%08x hlive h hr hnv hl.fl hl.r2 hl.ks hl.slot hk\n\n"
        % (p, p, p, p + 56, o, p))


def render():
    return (HEAD + "".join(site(*x) for x in SITES)
            + "".join(slot_site(*x) for x in SLOT_SITES) + "end Dc.Mach\n")


def main():
    text = render()
    if "--check" in sys.argv:
        if OUT.read_text() != text:
            sys.exit(f"{OUT} is stale; rerun {__file__}")
        return
    OUT.write_text(text)


if __name__ == "__main__":
    main()
